import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./Calendar.stories";
import Calendar from "./Calendar";

const { Basic } = composeStories(stories) as any;

describe("Calendar component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(<Calendar data-testid="calendar" />);
    expect(screen.getByTestId("calendar")).toBeInTheDocument();
  });

  it("allow to select a single date", () => {
    const onChange = jest.fn();
    render(<Calendar onChange={onChange} />);

    // no initial call on first render
    expect(onChange).toHaveBeenCalledTimes(0);

    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange).toHaveBeenCalledWith(expect.any(Date));
    expect(secondMonday).toHaveAttribute("aria-pressed", "true");

    const thirdFriday = screen.getAllByRole("button", { name: /Fri/ })[2];
    fireEvent.click(thirdFriday);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange).toHaveBeenCalledWith(expect.any(Date));
    expect(secondMonday).toHaveAttribute("aria-pressed", "false");
    expect(thirdFriday).toHaveAttribute("aria-pressed", "true");
  });

  it("allow to select a range of dates", () => {
    const onChange = jest.fn();
    render(<Calendar mode="range" onChange={onChange} />);

    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange.mock.calls[0][0]).toHaveLength(1);

    const thirdFriday = screen.getAllByRole("button", { name: /Fri/ })[2];
    fireEvent.click(thirdFriday);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange.mock.calls[1][0]).toHaveLength(2);

    expect(secondMonday).toHaveAttribute("aria-pressed", "true");
    expect(thirdFriday).toHaveAttribute("aria-pressed", "true");
  });

  it("allow to select a single date in range mode", () => {
    const onChange = jest.fn();
    render(<Calendar mode="range" onChange={onChange} />);

    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange.mock.calls[0][0]).toHaveLength(1);

    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange.mock.calls[1][0]).toHaveLength(2);

    expect(secondMonday).toHaveAttribute("aria-pressed", "true");
  });

  it("allow to select mutiple independant dates", () => {
    const onChange = jest.fn();
    render(<Calendar mode="multi" onChange={onChange} />);

    const secondMonday = screen.getAllByRole("button", { name: /Mon/ })[1];
    fireEvent.click(secondMonday);
    expect(onChange).toHaveBeenCalledTimes(1);
    expect(onChange.mock.calls[0][0]).toHaveLength(1);

    const fridays = screen.getAllByRole("button", { name: /Fri/ });
    fireEvent.click(fridays[1]);
    expect(onChange).toHaveBeenCalledTimes(2);
    expect(onChange.mock.calls[1][0]).toHaveLength(2);
    expect(secondMonday).toHaveAttribute("aria-pressed", "true");
    expect(fridays[1]).toHaveAttribute("aria-pressed", "true");

    fireEvent.click(fridays[1]);
    expect(onChange).toHaveBeenCalledTimes(3);
    expect(onChange.mock.calls[2][0]).toHaveLength(1);
    expect(fridays[1]).toHaveAttribute("aria-pressed", "false");

    fireEvent.click(fridays[1]);
    fireEvent.click(fridays[2]);
    expect(onChange).toHaveBeenCalledTimes(5);
    expect(onChange.mock.calls[4][0]).toHaveLength(3);
    expect(secondMonday).toHaveAttribute("aria-pressed", "true");
    expect(fridays[1]).toHaveAttribute("aria-pressed", "true");
    expect(fridays[2]).toHaveAttribute("aria-pressed", "true");
  });

  it("throws an error with invalid value", () => {
    expect(() => render(<Calendar value={[new Date()]} />)).toThrow(
      "Calendar 'value' must be a Date object when used in 'single' mode."
    );
    expect(() => render(<Calendar mode="range" value={new Date()} />)).toThrow(
      "Calendar 'value' must be an array of one or two Date objects when used in 'range' mode."
    );
    expect(() => render(<Calendar mode="multi" value={new Date()} />)).toThrow(
      "Calendar 'value' must be an array of Date objects when used in 'multi' mode."
    );
  });

  it("Allow to navigate months", async () => {
    consoleSpy.log.mockRestore();
    render(<Calendar defaultValue={new Date(2021, 5, 10)} />);

    const lastBtn = screen.getByLabelText("Go back 1 month");
    const nextBtn = screen.getByLabelText("Go forward 1 month");
    const monthSelect = screen.getByRole("combobox", { name: /month/ });

    // navigate back & forth to march
    fireEvent.click(lastBtn);
    fireEvent.click(lastBtn);
    fireEvent.click(lastBtn);
    fireEvent.click(lastBtn);
    fireEvent.click(nextBtn);
    expect(monthSelect).toHaveValue("2");

    // click on 2/4/21
    const secondAprilBtn = screen.getByLabelText("Fri Apr 02 2021");
    fireEvent.click(secondAprilBtn);
    expect(monthSelect).toHaveValue("3");
  });

  it("handle timezone offset", () => {
    // @see .env TZ variable forced to Pacific/Tahiti
    expect(new Date().getTimezoneOffset()).toBe(600);

    // without ignoring timezoneOffset, the displayed date will be one day before
    const { rerender } = render(
      <Calendar value={new Date("2019-01-02T00:00:00Z")} />
    );
    expect(
      screen.getByRole("button", { name: /Jan 01 2019/i })
    ).toHaveAttribute("aria-pressed", "true");

    // ignoring timezoneOffset, the displayed date will be specified utc day
    const getUTCDate = (value: string) => {
      const date = new Date(value);
      date.setMinutes(date.getMinutes() + date.getTimezoneOffset());
      return date;
    };
    rerender(<Calendar value={getUTCDate("2019-01-02T00:00:00Z")} />);
    expect(
      screen.getByRole("button", { name: /Jan 02 2019/i })
    ).toHaveAttribute("aria-pressed", "true");
  });

  it("Set year range depending on min & max dates", () => {
    const { rerender } = render(<Calendar />);

    // @see setupTest.js > system date is mocked to 2021
    // expect years to go from 1971 to 2071
    expect(screen.queryByRole("option", { name: "1970" })).toBeNull();
    expect(screen.getByRole("option", { name: "1971" })).toBeVisible();
    expect(screen.getByRole("option", { name: "2071" })).toBeVisible();
    expect(screen.queryByRole("option", { name: "2072" })).toBeNull();

    // with minDate=2000 > expect years to go from 2000 to 2100
    rerender(<Calendar minDate={new Date(2000, 0, 1)} />);
    expect(screen.queryByRole("option", { name: "1999" })).toBeNull();
    expect(screen.getByRole("option", { name: "2000" })).toBeVisible();
    expect(screen.getByRole("option", { name: "2100" })).toBeVisible();
    expect(screen.queryByRole("option", { name: "2101" })).toBeNull();

    // with maxDate=2100 > expect years to go from 2000 to 2100
    rerender(<Calendar maxDate={new Date(2100, 11, 31)} />);
    expect(screen.queryByRole("option", { name: "1999" })).toBeNull();
    expect(screen.getByRole("option", { name: "2000" })).toBeVisible();
    expect(screen.getByRole("option", { name: "2100" })).toBeVisible();
    expect(screen.queryByRole("option", { name: "2101" })).toBeNull();

    // with minDate=2010 & maxDate=2030 > expect years to go from 2010 to 2030
    rerender(
      <Calendar
        minDate={new Date(2010, 0, 1)}
        maxDate={new Date(2030, 11, 31)}
      />
    );
    expect(screen.queryByRole("option", { name: "2009" })).toBeNull();
    expect(screen.getByRole("option", { name: "2010" })).toBeVisible();
    expect(screen.getByRole("option", { name: "2030" })).toBeVisible();
    expect(screen.queryByRole("option", { name: "2031" })).toBeNull();
  });

  it("Do not allow to navigate outside year range", () => {
    render(<Calendar minDate={new Date(2019, 10, 1)} maxDate={new Date(2021, 2, 31)} />);

    const lastBtn = screen.getByLabelText("Go back 1 month");
    const nextBtn = screen.getByLabelText("Go forward 1 month");
    const monthSelect = screen.getByRole("combobox", { name: /month/ });
    const yearSelect = screen.getByRole("combobox", { name: /year/ });

    // click more than necessary on back button to go min month/year
    for (let i=0; i<20; i++) fireEvent.click(lastBtn);
    // should have stopped at nov 2019 (minDate)
    expect(monthSelect).toHaveValue("10");
    expect(yearSelect).toHaveValue("2019");

    // click more than necessary on forward button to go max month/year
    for (let i=0; i<40; i++) fireEvent.click(nextBtn);
    // should have stopped at mar 2021 (maxDate)
    expect(monthSelect).toHaveValue("2");
    expect(yearSelect).toHaveValue("2021");
  });

  it("set range end date to end of the day #1157", () => {
    const onChange = jest.fn();
    render(<Calendar mode="range" onChange={onChange} />);

    fireEvent.click(screen.getAllByRole("button", { name: /Mon/ })[1]);
    fireEvent.click(screen.getAllByRole("button", { name: /Fri/ })[2]);
    expect(onChange.mock.calls[1][0]).toHaveLength(2);
    const endDate = onChange.mock.calls[1][0][1];
    expect(endDate.getHours()).toEqual(23);
    expect(endDate.getMinutes()).toEqual(59);
    expect(endDate.getSeconds()).toEqual(59);
    expect(endDate.getMilliseconds()).toEqual(999);
  });

  it("starts weekdays at sunday for pacific time #1878", () => {
    const { container, getByLabelText } = render(
      <Calendar value={new Date("2023-12-12T00:00:00Z")} />
    );

    expect(getByLabelText("Tue Dec 12 2023")).toBeVisible();

    const weekdays = container.querySelectorAll("[class$='-weekday']");
    expect(weekdays[0].textContent).toEqual("Sun");
  });
});
